    var neg: bool = false;

    if (question[i] == '-') {
        neg = true;
        i += 1;
        if (i >= end or question[i] < '0' or question[i] > '9') return ArgumentError.SyntaxError;
    } else if (question[i] < '0' or question[i] > '9') {
        return ArgumentError.SyntaxError;
    }

    while (i < end and question[i] >= '0' and question[i] <= '9') {
        result = result * 10 + (question[i] - '0');
        i += 1;
    }

    if (neg) result = -result;

    // Now expect operators
