```zig
const std = @import("std");

pub const ArgumentError = error{
    UnsupportedQuestion,
    SyntaxError,
    DivisionByZero,
};

pub fn answer(question: []const u8) ArgumentError!i32 {
    if (!std.mem.startsWith(u8, question, "What is ")) return ArgumentError.UnsupportedQuestion;
    if (question.len < 9) return ArgumentError.SyntaxError;
    if (question[question.len - 1] != '?') return ArgumentError.UnsupportedQuestion;

    var i: usize = 8;
    const end = question.len - 1;

    // Skip spaces
    while (i < end and question[i] == ' ') i += 1;
    if (i >= end) return ArgumentError.SyntaxError;

    // Parse first number
    var result: i32 = 0;
    var neg: bool = false;

    if (question[i] == '-') {
        neg = true;
        i += 1;
        if (i >= end or question[i] < '0' or question[i] > '9') return ArgumentError.SyntaxError;
    } else if (question[i] < '0' or question[i] > '9') {
        return ArgumentError.SyntaxError;
    }

    while (i < end and question[i] >= '0' and question[i] <= '9') {
        result = result * 10 + (question[i] - '0');
        i += 1;
    }

    if (neg) result = -result;

    // Process operations
    while (i < end) {
        // Skip spaces
        while (i < end and question[i] == ' ') i += 1;
        if (i >= end) return ArgumentError.SyntaxError;

        // Must be an operator (not a number)
        if (question[i] == '-' or (question[i] >= '0' and question[i] <= '9')) {
            return ArgumentError.SyntaxError;
        }

        // Determine operator
        const op = blk: {
            if (std.mem.startsWith(u8, question[i..end], "plus")) {
                i += 4;
                break :blk 0;
            } else if (std.mem.startsWith(u8, question[i..end], "minus")) {
                i += 5;
                break :blk 1;
            } else if (std.mem.startsWith(u8, question[i..end], "multiplied by")) {
                i += 13;
                break :blk 2;
            } else if (std.mem.startsWith(u8, question[i..end], "divided by")) {
                i += 10;
                break :blk 3;
            } else {
                return ArgumentError.UnsupportedQuestion;
            }
        };

        // Skip spaces after operator
        while (i < end and question[i] == ' ') i += 1;
        if (i >= end) return ArgumentError.SyntaxError;

        // Must be a number
        neg = false;
        if (question[i] == '-') {
            neg = true;
            i += 1;
            if (i >= end or question[i] < '0' or question[i] > '9') return ArgumentError.SyntaxError;
        } else if (question[i] < '0' or question[i] > '9') {
            return ArgumentError.SyntaxError;
        }

        var num: i32 = 0;
        while (i < end and question[i] >= '0' and question[i] <= '9') {
            num = num * 10 + (question[i] - '0');
            i += 1;
        }

        if (neg) num = -num;

        // Apply
        switch (op) {
            0 => result += num,
            1 => result -= num,
            2 => result *= num,
            3 => {
                if (num == 0) return ArgumentError.DivisionByZero;
                result /= num;
            },
            else => unreachable,
        }
    }

    return result;
}
